import requests

def fetch_persons():
    url = 'https://jsonplaceholder.typicode.com/users'
    response = requests.get(url)
    persons = response.json()
    return persons

def main():
    persons = fetch_persons()

    print("Welcome to the Dinner Party!")

    for person in persons:
        name = person['name']
        email = person['email']

        greeting = f"Hello {name}, would you like to join our dinner?"
        response = input(greeting)

        if response == "yes":
            print(f"Great! We will send an invitation to {email}.")
        else:
            print(f"Ok, no problem then.")

if __name__ == '__main__':
    main()

