import json

def load_figures():
    with open('figures.json') as f:
        return json.load(f)

def select_dinner(figures):
    dinner = []
    while len(dinner) < 3:
        figure = random.choice(figures)
        if figure['age'] > 50 and 'scientist' in figure['occupation']:
            dinner.append(figure)
    return dinner

def main():
    figures = load_figures()
    dinner = select_dinner(figures)
    print("Dinner will be hosted by:")
    for figure in dinner:
        print(figure['name'])

if __name__ == '__main__':
    main()
